    ('environmental_sensor', '环境传感器', '基于 Bluetooth SIG Environmental Sensing 标准服务的温湿度、气压等环境数据采集设备。', '[{"uuid":"0000181a-0000-1000-8000-00805f9b34fb","name":"Environmental Sensing"},{"uuid":"0000180f-0000-1000-8000-00805f9b34fb","name":"Battery Service"},{"uuid":"0000180a-0000-1000-8000-00805f9b34fb","name":"Device Information"}]'::jsonb, '[{"key":"temperature_celsius","unit":"celsius","characteristicUuid":"00002a6e-0000-1000-8000-00805f9b34fb"},{"key":"relative_humidity","unit":"%","characteristicUuid":"00002a6f-0000-1000-8000-00805f9b34fb"},{"key":"pressure_hpa","unit":"hectopascal","characteristicUuid":"00002a6d-0000-1000-8000-00805f9b34fb"}]'::jsonb, '["仅解析标准 Environmental Sensing 特征；厂商私有格式需要客户端自行适配。","温度特征可能同时包含华氏/摄氏标志位，客户端上报前统一归一化为摄氏度。"]'::jsonb, '{"platforms":["android","ios"],"minAppVersion":"1.0.0","protocol":"ble-gatt","features":["temperature","humidity","pressure"]}'::jsonb, now()),
    ('heart_rate_monitor', '心率传感器', '基于 Bluetooth SIG Heart Rate 标准服务的心率带或心率传感器。', '[{"uuid":"0000180d-0000-1000-8000-00805f9b34fb","name":"Heart Rate"},{"uuid":"0000180f-0000-1000-8000-00805f9b34fb","name":"Battery Service"},{"uuid":"0000180a-0000-1000-8000-00805f9b34fb","name":"Device Information"}]'::jsonb, '[{"key":"heart_rate","unit":"bpm","characteristicUuid":"00002a37-0000-1000-8000-00805f9b34fb"}]'::jsonb, '["只解析 Heart Rate Measurement 的即时心率；RR 间期等派生指标由客户端计算后另行上报。","部分设备需要先订阅 Battery Service 才会开启心率通知，以厂商说明为准。"]'::jsonb, '{"platforms":["android","ios"],"minAppVersion":"1.0.0","protocol":"ble-gatt","features":["heart-rate"]}'::jsonb, now()),
    ('nordic_uart', 'Nordic UART 透传设备', '使用 Nordic UART Service（NUS）进行双向串口透传的 BLE 设备。', '[{"uuid":"6e400001-b5a3-f393-e0a9-e50e24dcca9e","name":"Nordic UART Service"},{"uuid":"00001800-0000-1000-8000-00805f9b34fb","name":"Generic Access"},{"uuid":"0000180a-0000-1000-8000-00805f9b34fb","name":"Device Information"}]'::jsonb, '[]'::jsonb, '["NUS 仅提供透传通道，载荷格式由设备固件决定；服务端不解析原始字节。","指标 key 与单位由客户端按固件协议解析后上报，服务端只做校验与归档。"]'::jsonb, '{"platforms":["android","ios"],"minAppVersion":"1.0.0","protocol":"ble-gatt","features":["uart-transparent"]}'::jsonb, now()),
    ('smart_scale', '智能体脂秤', '基于 Bluetooth SIG Body Composition 与 Weight Scale 标准服务的体脂秤。', '[{"uuid":"0000181b-0000-1000-8000-00805f9b34fb","name":"Body Composition"},{"uuid":"0000181d-0000-1000-8000-00805f9b34fb","name":"Weight Scale"},{"uuid":"0000180f-0000-1000-8000-00805f9b34fb","name":"Battery Service"},{"uuid":"0000180a-0000-1000-8000-00805f9b34fb","name":"Device Information"}]'::jsonb, '[{"key":"weight_kg","unit":"kg","characteristicUuid":"00002a9d-0000-1000-8000-00805f9b34fb"},{"key":"body_fat_percent","unit":"%","characteristicUuid":"00002a9c-0000-1000-8000-00805f9b34fb"},{"key":"bmi","unit":"kg/m2","characteristicUuid":"00002a9c-0000-1000-8000-00805f9b34fb"}]'::jsonb, '["体重单位可能为 kg 或 lb，客户端需按 Weight Scale Feature 归一化为千克后上报。","体脂率与 BMI 依赖厂商算法与用户身高配置，不同型号结果不可直接横向比较。"]'::jsonb, '{"platforms":["android","ios"],"minAppVersion":"1.0.0","protocol":"ble-gatt","features":["weight","body-composition"]}'::jsonb, now());
